W = 6
I, R = "Inkoop", "Recht"

# ---------- Inkoop MC (circulair inkopen en ethiek) ----------
mc("ir6-i01", W, I, "Wat is het belangrijkste verschil tussen groen en circulair inkopen?",
   ["Er is geen verschil", "Groen inkopen richt zich op minder milieu-impact; circulair inkopen op het zo lang mogelijk behouden van de waarde van grondstoffen en producten", "Circulair inkopen is altijd goedkoper", "Groen inkopen is alleen voor de publieke sector"], 1,
   "Circulair inkopen gaat uit van 'afval bestaat niet'. Een product kan groen zijn zonder circulair te zijn, zoals een zuinige printer die na gebruik wordt weggegooid.")
mc("ir6-i02", W, I, "Welk voorbeeld is het duidelijkst circulair inkopen?",
   ["Energiezuinige lampen kopen", "Licht als dienst afnemen, waarbij de leverancier eigenaar blijft van de armaturen en die terugneemt en hergebruikt", "Biologische koffie kopen", "Een elektrische dienstauto leasen"], 1,
   "Bij 'licht als dienst' houdt de leverancier belang bij een lange levensduur en hergebruik. Dat behoudt de waarde van producten en grondstoffen.")
mc("ir6-i03", W, I, "Een bedrijf meldt trots zijn duurzaamheidsprestaties in de jaarverslagen, maar duurzaamheid speelt geen rol in de strategie of de inkoopbeslissingen. In welke fase van het fasemodel duurzaam inkopen zit het?",
   ["Ontkenning", "Windowdressing", "Naleving wet- en regelgeving", "Drijfveer voor innovatie"], 1,
   "Bij windowdressing zit duurzaamheid in communicatie en marketing, niet in de businessstrategie. Het doel is vooral imago.")
mc("ir6-i04", W, I, "Na een negatief krantenartikel over verboden stoffen moeten leveranciers verklaren dat hun producten aan de milieuwetgeving voldoen. Welke fase is dit?",
   ["Windowdressing", "Naleving wet- en regelgeving", "Drijfveer voor kostenbesparingen", "Drijfveer voor maatschappelijke waarde"], 1,
   "Fase 3 wordt vaak gestart door een incident. Inkoop moet problemen met wetgeving voorkomen, bijvoorbeeld met leveranciersverklaringen.")
mc("ir6-i05", W, I, "Inkopers zoeken in de keten naar energie- en CO2-besparing, omdat dat ook kosten verlaagt, en doen audits bij leveranciers. Welke fase past?",
   ["Ontkenning", "Windowdressing", "Drijfveer voor kostenbesparingen", "Drijfveer voor maatschappelijke waarde"], 2,
   "In fase 4 is duurzaamheid een manier om reputatieschade te voorkomen én kosten te verlagen.")
mc("ir6-i06", W, I, "Welke norm hoort bij de hoogste fase van het fasemodel, waarin de inkoopfunctie volledig duurzaam is ingericht?",
   ["ISO 9001", "ISO 20400", "ISO 14001", "ISO 27001"], 1,
   "ISO 20400 is de richtlijn voor duurzaam inkopen. In fase 6 (maatschappelijke waarde) is de inkoopfunctie ingericht zoals ISO 20400 bedoelt.")
mc("ir6-i07", W, I, "Wat klopt over de NEVI-gedragscode?",
   ["Het is een wet waarop boetes staan", "Het is zelfregulering door de beroepsgroep, zonder wettelijke grondslag, met wederkerige verwachtingen voor inkopers en leveranciers", "Hij geldt alleen voor publieke inkopers", "Hij vervangt de Aanbestedingswet"], 1,
   "De code is geen wet en geen verplichting. Het is zelfregulering, juist ook waar geen specifieke wet bestaat. Ook leveranciers horen zich aan gedragsregels te houden.")
mc("ir6-i08", W, I, "Een inkoper accepteert een gratis weekend weg van een leverancier die meedoet aan een lopende aanbesteding. Welk principe van de NEVI-code schendt hij vooral?",
   ["Maatschappelijke waarde", "Integriteit en objectiviteit", "Deskundigheid en verantwoording", "Wederzijdse erkenning"], 1,
   "Integriteit en objectiviteit: niet laten beïnvloeden door persoonlijke belangen, belangenverstrengeling vermijden, beslissen op objectieve criteria, geen corruptie of omkoping.")
mc("ir6-i09", W, I, "Een inkoper gebruikt een AI-tool om offertes te scoren, maar kan niet uitleggen hoe de tool tot een rangorde komt. Welk principe raakt dit vooral?",
   ["Integriteit en objectiviteit", "Deskundigheid en verantwoording", "Maatschappelijke waarde", "Wederkerigheid"], 1,
   "Deskundigheid en verantwoording: besluiten kunnen uitleggen en verantwoorden, zorgvuldig omgaan met data en algoritmen, en bevooroordeelde besluiten voorkomen.")
mc("ir6-i10", W, I, "Wat is volgens de slide de 'moraal' bij ethische dilemma's?",
   ["Kies altijd de goedkoopste leverancier", "Er is vaak geen goed of fout antwoord, maar je moet zorgvuldig en transparant afwegen", "Laat de directie altijd beslissen", "Volg altijd de wet, verder niets"], 1,
   "Ethische dilemma's vragen een zorgvuldige en transparante afweging. Het NEVI-stappenplan helpt daarbij.")
mc("ir6-i11", W, I, "Wat is de eerste stap van het NEVI-stappenplan voor een ethisch dilemma?",
   ["Bedenk minimaal twee oplossingen", "Wat is het ethische dilemma?", "Kies de beste optie", "Houd een pitch voor de directie"], 1,
   "De volgorde: dilemma benoemen, feiten en ontbrekende informatie, waarden en belangen, minstens twee oplossingen, de beste optie, drie argumenten, een pitch en reflectie.")
mc("ir6-i12", W, I, "Welke SDG laat zich relatief makkelijk vertalen naar eisen of KPI's in een facilitair contract?",
   ["Vrede en justitie", "Verantwoorde consumptie en productie, bijvoorbeeld via afvalscheiding en hergebruikpercentages", "Leven onder water, alleen voor visserijbedrijven", "Partnerschap voor de doelen"], 1,
   "Doelen rond energie, afval en grondstoffen en arbeidsomstandigheden kun je vangen in eisen en KPI's, zoals een percentage hergebruikt meubilair of gescheiden afval.")

# ---------- Recht MC (koop en eigendom) ----------
mc("ir6-r01", W, R, "Wanneer is er sprake van consumentenkoop (art. 7:5 BW)?",
   ["Bij elke koop door een particulier", "Bij koop van een roerende zaak door een koper die niet handelt in de uitoefening van beroep of bedrijf, van een verkoper die dat wel doet", "Bij koop van een woning door een particulier", "Bij koop tussen twee bedrijven onder €10.000"], 1,
   "Alle drie de elementen zijn nodig: roerende zaak, particuliere koper en professionele verkoper. Een woning is geen roerende zaak, dus nooit consumentenkoop.")
mc("ir6-r02", W, R, "Wat is het belangrijkste gevolg van consumentenkoop?",
   ["De koop moet schriftelijk", "De regeling van koop is grotendeels dwingend recht (art. 7:6 lid 1 BW)", "De verkoper hoeft niet conform te leveren", "De koper heeft altijd 30 dagen bedenktijd"], 1,
   "Bij consumentenkoop kan niet ten nadele van de consument van de wet worden afgeweken. Bij andere koop is Titel 1 regelend recht.")
mc("ir6-r03", W, R, "Een bedrijf koopt een kantoorpand en tekent de koopakte. Heeft het drie dagen bedenktijd?",
   ["Ja, altijd bij onroerende zaken", "Nee, de bedenktijd van art. 7:2 lid 2 BW geldt alleen voor een particuliere koper van een woning", "Ja, als de akte bij de notaris is getekend", "Alleen als de verkoper een particulier is"], 1,
   "Art. 7:2 BW beschermt de particuliere koper van een woning: de koop moet schriftelijk en er is drie dagen bedenktijd. Een zakelijke koper van een kantoorpand heeft dat niet, tenzij afgesproken.")
mc("ir6-r04", W, R, "Wanneer is een zaak niet conform (art. 7:17 BW)?",
   ["Als de koper er spijt van heeft", "Als hij, gelet op de aard en de mededelingen van de verkoper, niet de eigenschappen heeft die de koper redelijkerwijs mocht verwachten, ook voor normaal gebruik", "Alleen als er een schriftelijke garantie is geschonden", "Alleen als het product binnen een week kapot gaat"], 1,
   "Conformiteit gaat over de redelijke verwachtingen. Ook zonder garantie geldt de wettelijke conformiteitseis.")
mc("ir6-r05", W, R, "Een zakelijke koper krijgt een garantie van één maand op ledverlichting, die na zes weken kapot gaat. Heeft de verkoper gelijk als hij weigert te herstellen?",
   ["Nee, ledverlichting moet jaren meegaan", "Ja, bij zakelijke koop mag een negatieve garantie de redelijke verwachtingen bijstellen (regelend recht)", "Nee, garanties korter dan een jaar zijn nietig", "Ja, maar alleen als de koper een consument is"], 1,
   "Een negatieve garantie beperkt de rechten van de koper. Dat mag bij zakelijke koop. Bij consumentenkoop niet: daar houdt de consument naast de garantie al zijn rechten (art. 7:6a BW).")
mc("ir6-r06", W, R, "Wat kan de koper volgens art. 7:21 BW vorderen bij non-conformiteit?",
   ["Alleen geld terug", "Aflevering van het ontbrekende, herstel of vervanging, op kosten van de verkoper", "Alleen een nieuw product van een ander merk", "Niets zonder schriftelijke garantie"], 1,
   "Daarnaast blijven de rechten uit Boek 6 (ontbinding, schadevergoeding) bestaan. Bij consumentenkoop kan prijsvermindering of ontbinding pas na een poging tot herstel of vervanging (art. 7:22 lid 2 BW).")
mc("ir6-r07", W, R, "Binnen welke termijn moet een consument klagen om in ieder geval op tijd te zijn?",
   ["Binnen 14 dagen na aflevering", "Binnen twee maanden na ontdekking van het gebrek (art. 7:23 BW)", "Binnen een jaar na aankoop", "Er geldt geen klachtplicht voor consumenten"], 1,
   "De koper moet binnen bekwame tijd klagen. Voor consumenten is klagen binnen twee maanden na ontdekking in ieder geval tijdig.")
mc("ir6-r08", W, R, "Een verkoper heeft niet betaald gekregen en wil de geleverde zaak terughalen, ook tijdens het faillissement van de koper. Welk recht gebruikt hij?",
   ["Eigendomsvoorbehoud", "Het recht van reclame (art. 7:39 BW)", "Opschortingsrecht", "Productaansprakelijkheid"], 1,
   "Met het recht van reclame haalt de verkoper de zaak terug. Het werkt ook in faillissement, maar alleen als de zaak nog in dezelfde staat is (art. 7:41 BW) en binnen korte vervaltermijnen.")
mc("ir6-r09", W, R, "Wat is het verschil tussen verjaring en verval?",
   ["Er is geen verschil", "Verjaring kan worden gestuit (bijvoorbeeld door een aanmaning), verval niet; na beide blijft een natuurlijke verbintenis over", "Verval duurt altijd langer", "Alleen verjaring geldt voor koop"], 1,
   "Na verjaring of verval is een recht niet meer afdwingbaar, maar er blijft een natuurlijke verbintenis (art. 6:3 BW). Alleen verjaring kun je stuiten.")
mc("ir6-r10", W, R, "Welke drie voorwaarden stelt art. 3:84 BW aan een geldige eigendomsoverdracht?",
   ["Betaling, levering en ondertekening", "Een geldige titel, beschikkingsbevoegdheid en levering", "Een notariële akte, inschrijving en betaling", "Een koopovereenkomst, een factuur en een garantie"], 1,
   "Betaling is geen voorwaarde voor eigendomsoverdracht. Daarom is een eigendomsvoorbehoud (art. 3:92 BW) of vooruitbetaling belangrijk voor de verkoper.")
mc("ir6-r11", W, R, "Maria verkoopt haar laptop aan Kees, maar mag hem nog een maand gebruiken voor haar scriptie. Welke vorm van levering is dit?",
   ["Brevi manu", "Longa manu", "Constitutum possessorium", "Feitelijke levering"], 2,
   "Bij constitutum possessorium houdt de verkoper de zaak na de verkoop onder zich, nu als houder voor de koper (art. 3:115 BW).")
mc("ir6-r12", W, R, "Punidas koopt ledverlichting zonder afspraken over levering. Wanneer en waar moet de verkoper leveren?",
   ["Binnen 30 dagen op het adres van Punidas", "Terstond (art. 6:38 BW) en op het adres van de verkoper (art. 7:9 jo. 6:41 BW)", "Binnen 14 dagen op een plek naar keuze van de verkoper", "Pas na betaling"], 1,
   "De termijn van 30 dagen (art. 7:9 lid 4 BW) geldt alleen bij consumentenkoop. Zonder afspraak geldt 'terstond'. De kosten van aflevering zijn voor de verkoper (art. 7:12 lid 1 BW). Zie oefenopdracht 6.2.")

# ---------- Open vragen ----------
op("ir6-io1", W, I, "Leg aan de hand van het fasemodel duurzaam inkopen uit hoe je in een casus herkent in welke fase een organisatie zit. Behandel minstens vier fasen.",
   "Je kijkt naar het motief. Fase 1, ontkenning: geen beleid, alleen de prijs telt. Fase 2, windowdressing: duurzaamheid alleen in communicatie en marketing. Fase 3, naleving: aanleiding is een incident of wet, leveranciers tekenen verklaringen. Fase 4, kostenbesparing: duurzaamheid omdat het reputatieschade voorkomt en kosten verlaagt, met audits in de keten. Fase 5, innovatie: leveranciers worden uitgedaagd en er is rapportage op directieniveau. Fase 6, maatschappelijke waarde: volledig geïntegreerd in organisatie en keten, ingericht volgens ISO 20400.",
   ["Herkenning via het motief", "Minstens vier fasen juist omschreven", "Juiste volgorde of nummering"])
op("ir6-io2", W, I, "Noem de drie overkoepelende principes van de NEVI-gedragscode en geef bij elk een voorbeeld uit de facilitaire inkooppraktijk.",
   "1. Maatschappelijke waarde: bij de inkoop van bedrijfskleding letten op arbeidsomstandigheden in de keten. 2. Integriteit en objectiviteit: geen geschenken aannemen van een leverancier tijdens een aanbesteding en een belang bij een leverancier melden. 3. Deskundigheid en verantwoording: de gunningsbeslissing kunnen uitleggen, zorgvuldig omgaan met data en AI, en cybersecurityrisico's in de keten signaleren.",
   ["Drie principes juist genoemd", "Bij elk een passend facilitair voorbeeld"])
op("ir6-io3", W, I, "Geef drie voorbeelden van circulair inkopen in facility management en leg bij één voorbeeld uit hoe je dit in een aanbesteding meeneemt.",
   "Voorbeelden: gerefurbished kantoormeubilair, terugnamegaranties op bedrijfskleding, licht als dienst, tapijttegels die worden teruggenomen voor recycling, catering met verpakkingsvrij servies. In een aanbesteding: bij meubilair bijvoorbeeld als eis of gunningscriterium een minimumpercentage hergebruikte materialen, een terugnamegarantie aan het einde van de levensduur, en een KPI op het hergebruikpercentage in het contract.",
   ["Drie passende circulaire voorbeelden", "Uitwerking hoe je het in een aanbesteding meeneemt (eis, gunningscriterium of KPI)"])
op("ir6-ro1", W, R, "Leg uit wat het bewijsvermoeden van art. 7:18 lid 2 BW inhoudt, voor wie het geldt, en welke termijn je volgens de slide en volgens de huidige wet gebruikt.",
   "Openbaart zich bij consumentenkoop binnen een bepaalde termijn na aflevering een gebrek, dan wordt vermoed dat de zaak bij aflevering al niet conform was. De verkoper moet dan het tegendeel bewijzen. Het geldt alleen bij consumentenkoop. Kritische noot: de slide noemt 6 maanden; volgens mij is de termijn sinds 2022 (Europese richtlijn) verlengd naar een jaar. Vraag de docent welke termijn op het tentamen telt.",
   ["Inhoud bewijsvermoeden (vermoeden non-conformiteit, bewijslast verkoper)", "Alleen bij consumentenkoop", "Termijn met kanttekening (slide 6 maanden, wet waarschijnlijk 1 jaar)"])
op("ir6-ro2", W, R, "Wat is productaansprakelijkheid en wanneer is bij consumentenkoop toch de verkoper aansprakelijk?",
   "Bij productaansprakelijkheid is de producent aansprakelijk voor schade door een gebrekkig product (art. 6:185 BW). Bij consumentenkoop is de verkoper toch aansprakelijk (art. 7:24 BW) als hij het gebrek kende of behoorde te kennen, als hij heeft toegezegd dat het gebrek er niet was, of als het gaat om zaakschade waarvoor de producent door de franchise van €500 niet aansprakelijk is.",
   ["Producent aansprakelijk, art. 6:185", "Uitzonderingen verkoper, art. 7:24 (minstens twee)"])
op("ir6-ro3", W, R, "Leg de begrippen houder, bezitter en eigenaar uit en beschrijf de drie vormen van levering zonder feitelijke overdracht (art. 3:115 BW) met een voorbeeld.",
   "Houder: houdt een zaak voor een ander (bijvoorbeeld een huurder). Bezitter: houdt een zaak voor zichzelf, middellijk of onmiddellijk. Eigenaar: heeft het meest omvattende recht op de zaak. Constitutum possessorium: de verkoper houdt de zaak na verkoop voor de koper (Maria gebruikt haar verkochte laptop nog een maand). Brevi manu: de koper had de zaak al als houder (Wibi koopt de piano die hij huurde). Longa manu: een derde houdt de zaak en gaat die nu voor de koper houden (het verkochte paard blijft bij de manege).",
   ["Houder, bezitter en eigenaar juist", "Drie vormen van 3:115 juist", "Bij elke vorm een passend voorbeeld"])

# ---------- Casussen ----------
cs("ir6-ic1", W, I, "Ethisch dilemma: bedrijfskleding voor de schoonmakers",
   "Je bent inkoper bij een ziekenhuis en koopt bedrijfskleding voor 600 schoonmakers en servicemedewerkers. Leverancier A is 30% goedkoper, maar er zijn berichten over slechte arbeidsomstandigheden in de fabriek in Bangladesh. Leverancier B is duurder, gecertificeerd op eerlijke productie en biedt een terugnamegarantie voor oude kleding. De directie wil dit jaar €80.000 besparen op facilitaire kosten. De accountmanager van A biedt je kaartjes aan voor een concert 'als bedankje voor het fijne contact'.",
   [("Werk de eerste vier stappen van het NEVI-stappenplan uit.",
     "1. Dilemma: kostenbesparing tegenover verantwoorde arbeidsomstandigheden en duurzaamheid. 2. Feiten: A is 30% goedkoper, er zijn berichten over slechte arbeidsomstandigheden, B is gecertificeerd en neemt terug; missende informatie: of de berichten kloppen, auditrapporten, de TCO inclusief levensduur en terugname. 3. Waarden en belangen: maatschappelijke waarde, reputatie van het ziekenhuis, het budget van de directie, de belangen van medewerkers in de keten. 4. Oplossingen: B kiezen en elders besparen; A kiezen onder voorwaarde van een onafhankelijke audit en verbeterplan; of een nieuwe uitvraag met eisen aan eerlijke productie.",
     ["Dilemma juist benoemd", "Feiten en ontbrekende informatie", "Waarden en belangen", "Minstens twee oplossingen"]),
    ("Welke keuze adviseer je? Geef drie argumenten en betrek TCO en de NEVI-code.",
     "Bijvoorbeeld B. Argumenten: maatschappelijke waarde (NEVI-principe 1) en het risico op reputatieschade voor een zorginstelling; de TCO kan meevallen door langere levensduur en terugname; en transparante verantwoording naar de directie (principe 3), met besparingen op andere categorieën. Een onderbouwd advies voor A met strikte voorwaarden kan ook, als het dilemma eerlijk wordt afgewogen.",
     ["Duidelijke keuze", "Drie argumenten", "TCO en NEVI-code betrokken"]),
    ("Hoe ga je om met het aanbod van de concertkaartjes?",
     "Niet aannemen. Dit raakt het principe integriteit en objectiviteit: je mag je niet laten beïnvloeden door persoonlijke voordelen, zeker niet tijdens een inkoopbeslissing. Meld het aanbod bij je leidinggevende of volgens de integriteitsregels van het ziekenhuis.",
     ["Afwijzen met juist principe", "Melden of transparant maken"])])
cs("ir6-ic2", W, I, "Duurzaamheid bij een gemeente",
   "Gemeente Groenstad zegt in haar persberichten 'de groenste gemeente van Nederland' te willen zijn. In de praktijk gunt de afdeling inkoop vrijwel alles op laagste prijs. Na een artikel over giftige stoffen in speeltoestellen moeten leveranciers nu een verklaring tekenen. De nieuwe wethouder wil dat inkoop 'echt bijdraagt aan de circulaire economie'.",
   [("In welke fase(n) van het fasemodel zit Groenstad nu? Onderbouw met de casus.",
     "Een mix van fase 2 (windowdressing: groene persberichten maar laagste prijs in de praktijk) en fase 3 (naleving: na een incident leveranciersverklaringen over verboden stoffen). Er is geen sprake van fase 4 of hoger, want duurzaamheid zit nog niet in de inkoopbeslissingen.",
     ["Fase 2 herkend met bewijs", "Fase 3 herkend met bewijs"]),
    ("Welke drie concrete stappen adviseer je om naar fase 4 of 5 te groeien?",
     "Bijvoorbeeld: gunnen op BPKV of TCO in plaats van laagste prijs, met duurzaamheids- en circulariteitscriteria; per categorie (meubilair, verlichting, kleding) circulaire eisen en KPI's opnemen, zoals hergebruikpercentages; met leveranciers innovatie uitdagen via marktconsultaties; en rapporteren op directieniveau met een inkoopdashboard met duurzaamheidsdoelen.",
     ["Drie concrete stappen", "Stappen passen bij fase 4 of 5 (kosten/keten, innovatie, rapportage)"]),
    ("Leg aan de wethouder het verschil uit tussen groen en circulair inkopen, met een voorbeeld uit de gemeente.",
     "Groen inkopen vermindert de milieu-impact, zoals energiezuinige straatverlichting. Circulair inkopen behoudt zo lang mogelijk de waarde van producten en grondstoffen, zoals verlichting als dienst waarbij de leverancier armaturen terugneemt en hergebruikt, of gerefurbished meubilair voor het stadhuis.",
     ["Verschil juist", "Passend gemeentelijk voorbeeld"])])
cs("ir6-rc1", W, R, "Koffiemachines en een kantoorpand",
   "Facilitair bedrijf CleanCo (40 medewerkers) koopt zonder schriftelijk contract tien professionele koffiemachines bij KoffieKoning. De verkoper zei: 'Deze machines gaan jaren mee.' Er is niets afgesproken over levering en betaling. KoffieKoning houdt zich het eigendom voor tot volledige betaling. Na drie weken gaan vier machines kapot.\nTegelijk koopt CleanCo een bedrijfspand van Vastgoed BV. De koopakte is getekend en CleanCo heeft de sleutels gekregen.\nEen medewerker van CleanCo koopt privé bij KoffieKoning een espressomachine met 'één maand garantie'. Die gaat na zes weken kapot.",
   [("Welke rechten heeft CleanCo bij de vier kapotte machines? Noem de artikelen.",
     "Er is geen consumentenkoop, dus regelend recht, maar partijen hebben niets afgesproken en dus geldt de wet. Gezien de mededeling 'gaan jaren mee' en de aard van de machines mocht CleanCo verwachten dat ze langer dan drie weken werken. Ze zijn dus niet conform (art. 7:17 BW). CleanCo heeft recht op herstel of vervanging (art. 7:21 BW), moet binnen bekwame tijd klagen (art. 7:23 BW) en houdt de rechten uit Boek 6.",
     ["Geen consumentenkoop, wet geldt bij gebrek aan afspraken", "Non-conformiteit, art. 7:17", "Herstel/vervanging, art. 7:21 (en klachtplicht)"]),
    ("Is CleanCo al eigenaar van de koffiemachines en van het pand?",
     "Machines: nee, nog niet, zolang niet volledig is betaald; KoffieKoning heeft een eigendomsvoorbehoud (art. 3:92 BW). Zonder dat voorbehoud was CleanCo bij levering eigenaar geworden, want betaling is geen voorwaarde (art. 3:84 BW). Pand: nee. Levering van een onroerende zaak vereist een notariële akte en inschrijving in de openbare registers (Kadaster), art. 3:89 BW. De koopakte en de sleutels zijn niet genoeg. CleanCo kan ook niet meer terug: de bedenktijd van art. 7:2 BW geldt alleen voor een particuliere koper van een woning.",
     ["Machines: eigendomsvoorbehoud art. 3:92", "Pand: akte en inschrijving art. 3:89", "Geen bedenktijd voor zakelijke koper"]),
    ("Heeft KoffieKoning gelijk als zij herstel van de privé-espressomachine weigert vanwege de garantie van één maand?",
     "Nee. Dit is consumentenkoop (art. 7:5 BW), dus is de regeling grotendeels dwingend (art. 7:6 lid 1 BW). De garantie kan de rechten van de consument niet inperken (art. 7:6a BW). Een espressomachine hoort langer dan zes weken mee te gaan (art. 7:17 BW), en omdat het gebrek zich snel na aflevering openbaart, geldt het bewijsvermoeden van art. 7:18 lid 2 BW. De medewerker heeft recht op herstel of vervanging (art. 7:21 BW).",
     ["Consumentenkoop herkend, dwingend recht", "Garantie perkt rechten niet in (7:6a)", "Bewijsvermoeden 7:18 lid 2 en herstel/vervanging 7:21"])])
